class Solution {
public:
    int minimumTime(string s) {
        int n = (int)s.size();
        int pref = 0;   // count of '1's in s[0..m-1]
        int minL = 0;   // min over j in [0..m] of (j - 2*pref[j])
        int best = 0;   // min candidate over all m
        for (int m = 0; m <= n; m++) {
            int L = m - 2 * pref;
            if (L < minL) minL = L;
            int R = 2 * pref - m;
            int cand = R + minL;
            if (cand < best) best = cand;
            if (m < n && s[m] == '1') pref++;
        }
        return n + best;
    }
};
